<template><div><div class="toolbar"><h3>订阅管理</h3><el-button type="primary" @click="open">新增订阅</el-button></div><el-table :data="items" border><el-table-column prop="name" label="名称"/><el-table-column prop="connection.connectionCode" label="连接"/><el-table-column prop="topicFilter" label="主题过滤器"/><el-table-column prop="qos" label="QoS" width="80"/><el-table-column prop="consumerCode" label="消费者"/><el-table-column label="状态"><template #default="{row}"><el-tag>{{ row.status === 'enabled' ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button size="small" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="visible" title="新增订阅" width="500px"><el-form :model="form" label-width="110px"><el-form-item label="连接"><el-select v-model="form.connectionId"><el-option v-for="item in connections" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="编码"><el-input v-model="form.subscriptionCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="主题"><el-input v-model="form.topicFilter" placeholder="xn/+/+/status"/></el-form-item><el-form-item label="QoS"><el-select v-model="form.qos"><el-option v-for="item in [0,1,2]" :key="item" :label="String(item)" :value="item"/></el-select></el-form-item><el-form-item label="消费者"><el-input v-model="form.consumerCode" placeholder="device-manager"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import http from '../../api/http'; const items=ref<any[]>([]); const connections=ref<any[]>([]); const visible=ref(false); const form=reactive<any>({connectionId:null,subscriptionCode:'',name:'',topicFilter:'',qos:1,consumerCode:'',enabled:true}); async function load(){const [a,b]=await Promise.all([http.get('/mqtt/subscriptions'),http.get('/mqtt/connections')]);items.value=a.data;connections.value=b.data;} function open(){Object.assign(form,{connectionId:null,subscriptionCode:'',name:'',topicFilter:'',qos:1,consumerCode:'',enabled:true});visible.value=true;} async function save(){try{await http.post('/mqtt/subscriptions',{...form,status:form.enabled?'enabled':'disabled'});ElMessage.success('保存成功');visible.value=false;await load();}catch(e:any){ElMessage.error(e.response?.data?.message||'保存失败');}} async function remove(row:any){await ElMessageBox.confirm('确定删除该订阅吗？','确认操作');await http.delete(`/mqtt/subscriptions/${row.id}`);await load();ElMessage.success('删除成功');} onMounted(load);</script>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.toolbar h3{margin:0}</style>
